INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizza Quest', 'Join the Teenage Mutant Ninja Turtles in their quest to defeat evil and eat pizza. In Nickelodeon''s free and fun online action game, you can play as Michelangelo, Raphael, Donatello and Leonardo and take down baddies in the mean streets of New York City. It''s up to you to use the Turtles'' special abilities to save the world from enemies like the Kraang, the Foot Clan and more. Take on multiple bosses at once to beat the game! Play Teenage Mutant Ninja Turtles: Pizza Quest and other free online quizzes and games now at Nick.com.' FROM games WHERE igdb_id = 305489 ON CONFLICT (game_id, language_code) DO NOTHING;
