INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wǒ de Tǎnkè Wǒ de Tuán', 'Dive into My Tanks, My Legion - Large-Scale Team Battle Strategy Game, the ultimate mobile experience for tank warfare enthusiasts! Command powerful armored vehicles, forge unbreakable alliances, and conquer the world in this thrilling strategy game. Prepare for intense tank battles, strategic deployments, and large-scale team operations. Whether you are a seasoned strategist or a newcomer to the genre, get ready to immerse yourself in a world of explosive action and tactical brilliance. This MMO strategy game allows you to build your tank legion and lead your team to victory on the battlefield.' FROM games WHERE igdb_id = 369854 ON CONFLICT (game_id, language_code) DO NOTHING;
