INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Wizards', 'Puzzle Wizards is a cozy co-op puzzle MMO from the creators of Puzzle Pirates (2003). Create your wizard and join a magical world of puzzling wizardry! Harvest, craft and battle by playing three respective puzzles, where you own skill makes the difference to your results. Join co-op adventures in the wilds and defeat nefarious spirits and worse to gather resources and loot, then return to your cozy Wizard village and guild to decorate, craft, socialize and make the world a better place.' FROM games WHERE igdb_id = 243266 ON CONFLICT (game_id, language_code) DO NOTHING;
