INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('saturnalia--1', 142101, '2022-10-27', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5p66.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1u69.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saturnalia', 'Saturnalia is a survival-horror adventure inspired and heavily influenced by the folklore of Sardinia, Italy, a region rich with unique traditions and culture. You play as four characters, experiencing a deeply connected storyline that ties back to the haunting traditions of this ancient village. The village itself is an elaborate maze with no two iterations being precisely the same - you will have to explore and solve the mysteries of the game largely unguided. Die, and watch the village reconfigure itself into a new form. Solve puzzles and open shortcuts to new areas with tools and items you find along the way, unlocking every piece of the story with different characters, each suited for another aspect of exploration and investigation. With a limited supply of matches to light your way and darkness encroaching, can you find your way through the fog to reveal the truth? Or will you be engulfed by the secrets this town doesn’t want you to know?' FROM games WHERE igdb_id = 142101 ON CONFLICT (game_id, language_code) DO NOTHING;
