INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frightence', 'Frighthence is a short, intense first-person horror experience. You are the janitor who works at the infamous Apartment #17, which is the seed of many eeire tales and bloodcurdling urban legends... The apartment recently got an eviction notice and tonight, you must check every resident’s flat to make sure that everybody has left. Soon you will realize that things are not the way they seem in this dreadful apartment…' FROM games WHERE igdb_id = 193299 ON CONFLICT (game_id, language_code) DO NOTHING;
