INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic 3 Timelines SMS Remake', 'A fanmade remake of both Sonic the Hedgehog Chaos and Sonic the Hedgehog Triple Trouble for Sega Game Gear, featuring new characters and habilities, new zones and levels, red star rings to unlock new stages, blue spheres special stages, Time Stones, a 16 bit music mode, a hub world, Ultra transformations, a pause menu, a debug mode and cheats, new color palettes and new player camera, gamepad support, 30 and 60 fps support, 4:3, widescreen and ultrawide.' FROM games WHERE igdb_id = 227802 ON CONFLICT (game_id, language_code) DO NOTHING;
