INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under Maintenance', 'After a rough day at work, all you want to do is settle in with your favorite otome game, only to realize it''s gone down for maintenance. How will you pass these troubling times? Risk going to a watering hole to drown your sorrows in a beverage of choice? Begrudgingly scroll through a dating app to meet your love for the night? Either way - adventure, shenanigans, and hot singles in your area await! Disclaimer: heartache probable - choose wisely.' FROM games WHERE igdb_id = 215428 ON CONFLICT (game_id, language_code) DO NOTHING;
