INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great War of Jorth', 'The Great War of Jorth (GWOJ) has the look and sound of a classic 16-bit JRPG. It will satisfy the nostalgic itch of any gamer that remembers playing the greats of the 16-bit era. Our fully voiced game will immerse you in a rich story where the outcome is determined by your choices.' FROM games WHERE igdb_id = 187643 ON CONFLICT (game_id, language_code) DO NOTHING;
