INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 2: Cloud Version', 'Players join rookie police officer Leon Kennedy and college student Claire Redfield, who are thrust together by a disastrous outbreak in Raccoon City that transformed its population into deadly zombies. Both Leon and Claire have their own separate playable campaigns, allowing players to see the story from both characters’ perspectives. The fate of these two fan favorite characters is in the player''s hands as they work together to survive and get to the bottom of what is behind the terrifying attack on the city.' FROM games WHERE igdb_id = 217561 ON CONFLICT (game_id, language_code) DO NOTHING;
