INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ciudad Anómala de Buenos Aires', 'Ciudad Anómala de Buenos Aires is an interactive narrative of strange but true stories that took place in the Autonomous City of Buenos Aires. It has several mini games, humor, and constant interaction with mysterious and ghostly characters. Moreover, it is riddled with references to Argentine culture (from Borges to Cha Cha Cha) and the video games that shaped us.' FROM games WHERE igdb_id = 271206 ON CONFLICT (game_id, language_code) DO NOTHING;
