INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark Adventure', 'Shark Adventure puts you in the role of a shark and your primary focus is to acquire as many stars as you can, while avoiding obstacles that come your way. It''s a very engaging and impressive game with lots of fun and enjoyable mechanics. This is not a simple game, it requires a lot of precision and attention. But it goes to show how exciting and fun this type of experience actually is.' FROM games WHERE igdb_id = 192041 ON CONFLICT (game_id, language_code) DO NOTHING;
