INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomber Panda', 'Help the ''Bomber Panda'' save his species from extinction by... blowing stuff up! This fun and challenging game has 31 levels of increasing difficulty for you to blast through. Collect power-ups to increase your bomb capacity, explosion size and walking speed. Avoid or blast the aggressive enemies while you try to find the exit.' FROM games WHERE igdb_id = 198165 ON CONFLICT (game_id, language_code) DO NOTHING;
