INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ranger Quest: The Adventure Begins', 'The adventure begins by navigating your way through the Sanctuary of the Orbs. A mysterious quest, the elemental orbs lying in wait for the ranger to claim and an ancient map to be remade. The Sanctuary of the Orbs is no ordinary building as the corridors twist and turn like a maze.' FROM games WHERE igdb_id = 367725 ON CONFLICT (game_id, language_code) DO NOTHING;
