INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deepspace', 'DEEPSPACE is an innovative Web3 strategy exploration MMO set in an expansive space environment. It integrates a sophisticated economy system using DPS, its native in-game token, along with NFT-based assets, providing players with genuine ownership of their in-game assets. The game is structured into multiple distinct stages, each offering a unique gaming experience, with The Hangar serving as the gateway to the vast DEEPSPACE universe.
