INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goetia 2', 'What could happen to two lovers who decided for a short break in Venice, Italy? Among all the possible scenarios, being pulled apart and tricked by a demon is certainly not what Daphné and Luca were expecting. Awakened as a pure soul in a twisted world he doesn’t understand, Luca is trapped in the reality of Buer, a demon with ulterior motives.' FROM games WHERE igdb_id = 200803 ON CONFLICT (game_id, language_code) DO NOTHING;
