INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dango Thief', 'Kazuki awakes one morning to find that he no longer exists. Play a game of hide n'' seek in this psychological horror RPG game in order to reclaim his existence. You only have 7 days to win. Explore the town by day, survive fatal nightmares by night, and discover the mysteries of the Dreamscape.' FROM games WHERE igdb_id = 242539 ON CONFLICT (game_id, language_code) DO NOTHING;
