INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '第一千零二夜的童话', '漫无目的的都市、永无止境的日常。 这里没有超现实的人和事物，有的只是青春期的少年少女们上演的日常与非日常。 没有一件东西比现实更沉重，也没有一件东西比爱更深奥。 但问题是，你能爱上那个不完美、不梦幻、甚至满身疮痍的对象吗？ 你能爱上你自己吗？' FROM games WHERE igdb_id = 188186 ON CONFLICT (game_id, language_code) DO NOTHING;
