INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VariDungeon', 'In VariDungeon, you are a hero exploring a dungeon. It may sound classic, but each run is different because its structure changes every time you start again ! Power-ups, enemies, bosses, traps, ... You need to adapt to all these elements in order to defeat the final boss and save the King !' FROM games WHERE igdb_id = 307350 ON CONFLICT (game_id, language_code) DO NOTHING;
