INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Paradise: Digital Deluxe Edition', 'Welcome to Arcade Paradise, the 90’s-fuelled retro arcade adventure. You play as Ashley, and you’ve just been given the keys to the family laundromat. Rather than washing rags for a living, you decide to turn the laundromat into the ultimate arcade. Choose from over 35 games to be in the arcade inspired by three decades of gaming – all of which are playable with high scores to set. Stay one step ahead of your father, manage and invest profits, and build your very own Arcade Paradise!' FROM games WHERE igdb_id = 213329 ON CONFLICT (game_id, language_code) DO NOTHING;
