INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strategic Command: American Civil War', 'For the first time in the series’ history, Strategic Command will be taking you to the 19th century battlefields of the American Civil War. In this turn-based strategy game, you will control the armies, research, production and diplomatic policy of either the Union or the Confederacy during a time of great innovation and dramatic battles. Your decisions will determine whether the United States leaves this conflict as one nation or two.' FROM games WHERE igdb_id = 204783 ON CONFLICT (game_id, language_code) DO NOTHING;
