INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Compound', 'COMPOUND is a randomized, rogue-lite, free-roaming shooter for Virtual Reality veterans. Duck and dodge around enemy fire in a tough-as-nails retro FPS with multiple locomotion options. Prepare to die - a lot - until you are good enough to reach the heart of The Corporation and take back what belongs to everyone...' FROM games WHERE igdb_id = 28927 ON CONFLICT (game_id, language_code) DO NOTHING;
