INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Six Hours at Hugo''s', 'You are an unemployed college junior who is strapped for cash. While browsing the Yellow Pages, you notice an ad for a night watchman position at Hugo''s Hole in the Wall. It looks simple enough, and you could definitely use the money. You decide to give them a call and see when you can start.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 273855 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
