INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hentai: Nazi Girl', 'HENTAI: NAZI GIRL is a satirical 3rd person shooter where you play as a sexy naked girl. You will have to destroy the enemies, evil and dangerous, also go to their base, where you need to kill everyone (unexpectedly, right?), you need to collect propaganda posters (and they contain jokes with elements of black humor, be sure to read it). After collecting all the propaganda posters, you need to find the hidden invitation to the club. And then a new big enemy will appear and you will be allowed to destroy the eyes lying on the ground, which indicate a connection with the enemy.' FROM games WHERE igdb_id = 327393 ON CONFLICT (game_id, language_code) DO NOTHING;
