INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PopSlinger', 'PopSlinger is a vibrant, narrative-focused musical shooter inspired by ‘80s and ‘90s New Retro culture. Join Ria Carbon, a funky heroine on a stylish quest to save the world from sinister invaders from another dimension using soda-powered guns. Backing Ria up is former PopSlinger heroine, Gin! Experience the whimsical story of Ria and Gin as they fight against the "Corazones", people whose hearts have been corrupted by the dark forces from the other dimension, all while grooving to a fully dynamic soundtrack that reacts to your in-game performance in real-time.' FROM games WHERE igdb_id = 186701 ON CONFLICT (game_id, language_code) DO NOTHING;
