INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperliminal', 'Welcome to Hyperliminal, a horror/exploration/fever-dream experience. The game itself is narration and exploration-based with some action to keep things interesting. You will explore a strange dreamscape and witness sites ranging from gigantic food to a town overtaken by arachnids. Unravel the mystery of the recurring nightmare while keeping safe a safe distance from the horrors that live within.' FROM games WHERE igdb_id = 201960 ON CONFLICT (game_id, language_code) DO NOTHING;
