INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astral Flux', 'Astral Flux is an action-platformer with roguelite elements. Join two scrappers who are lost in space and find themselves caught up in an intergalactic mystery. Traverse hostile alien planets, discover dark secrets, and face powerful foes in combat. Death is inevitable, but it’s only the beginning. Carve a new path forward using the knowledge from your previous attempts. You’ll need to sharpen your skills to unravel this mystery.' FROM games WHERE igdb_id = 193273 ON CONFLICT (game_id, language_code) DO NOTHING;
