INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miraculous: Rise of the Sphinx', 'Paris needs a hero! Once again, the city of lights is in trouble as it faces a new menace—the most threatening sentimonster ever created is about to take control! As you take on the personna’s of the globally renowned superheroez Ladybug and Cat Noir, you’ll need to unveil the diabolical plan hatched by archvillain Hawk Moth—and squash it! Immerse yourself into the magical world of Miraculous and level up your superpowers as you embark on your biggest journey yet!' FROM games WHERE igdb_id = 216552 ON CONFLICT (game_id, language_code) DO NOTHING;
