INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duels of Fortune', 'Duels of Fortune is an expressive 2.5D indie fighting game with a free-flowing combo system, unique and crazy characters, and lots of engaging singleplayer content. The game uses a simple input system that makes it accessible to beginners of the genre, while remaining mechanically rich in both universal and character-specific abilities. It''s a brand-new kind of fighting game experience for players of all skill levels.' FROM games WHERE igdb_id = 138441 ON CONFLICT (game_id, language_code) DO NOTHING;
