INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostwriter', 'Ghostwriter is a singleplayer typing game that pits your words-per-minute against poltergeists who have nothing better to do. Type whatever shows up on the monitor and meet your quota before the time limit. Encounter a variety of ghost types that will interfere in different ways. Buy upgrades and powerups to give yourself an advantage. Improve your words-per-minute and have fun while you are at it!' FROM games WHERE igdb_id = 249418 ON CONFLICT (game_id, language_code) DO NOTHING;
