INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survive Till Morning', '“Survive Till Morning” is a first person Dark fantasy horror - created by one person. The focus of the game is the story and its atmosphere, also the game is filled with: puzzles, achievements, references, different endings and gameplay styles (no shooting system). The approximate duration of the game - two hours.' FROM games WHERE igdb_id = 223028 ON CONFLICT (game_id, language_code) DO NOTHING;
