INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shechu de Fubao', 'A Blessing for the Herd is a morality tale about China''s "996" system of overworking employees, aimed to expose the societal and cultural structures behind the "996" system. Take control of a fledging e-commerce startup, manage investor funds and employees, and grow your customer base -- but be warned, pushing your employees to the edge can have devastating consequences. As the company expands, the stories of you and six other employees intertwine, as you work overtime to fulfil impossible investor expectations.' FROM games WHERE igdb_id = 255624 ON CONFLICT (game_id, language_code) DO NOTHING;
