INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Twister', 'Soar through the sky battling against invaders in this all-new fantasy endless shooter from legendary game creator, Yu Suzuki. Players will assume the role of Princess Arch fighting back against bizarre invaders to save their planet from destruction. They’ll rain down their homing arrows to trace graceful arcs of light across beautiful, artfully crafted stages, before they pierce their foes. With a fun and easy touchscreen swipe-shooting gameplay mechanic, the destiny of the planet is in the player’s hands.' FROM games WHERE igdb_id = 203458 ON CONFLICT (game_id, language_code) DO NOTHING;
