INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cazzarion: Demon Hunting', 'Demons are troubling here. Kill the brood of evil and send it back to hell. Standard weapons (Assault Rifle, Shotgun) and special weapons (BoomShot, Reaper, ....) are available. As opponents, the demons of hell are fighting against you. Choose your weapon and shoot ("Groarrr.....BOOOOOM")' FROM games WHERE igdb_id = 202498 ON CONFLICT (game_id, language_code) DO NOTHING;
