INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another Reigny Day', 'Take up your trusty bow and siege weapons to repel a fairy tale assault in fully immersive VR! Did the enemies smash down your gate with their battering ram? Quick-throw your hip axes to keep them from mounting the stairs! Spend your gold wisely and you can even DUAL WIELD MAGIC STAFFS!' FROM games WHERE igdb_id = 368884 ON CONFLICT (game_id, language_code) DO NOTHING;
