INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem Warriors: Three Hopes', 'Prepare for a different story set in the same universe as Fire Emblem: Three Houses. Shez, a mercenary whose team was decimated by Byleth in battle, joins the military academy of Garreg Mach Monastery and becomes a student in one of three classes, each including students from one of the three nations of the continent of Fódlan. Like in Three Houses, the game allows players to decide which class to join, leading to different story paths and playable characters.' FROM games WHERE igdb_id = 191396 ON CONFLICT (game_id, language_code) DO NOTHING;
