INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orcen Axe', 'Orcen Axe is a 2D pixel metroidvania. As the orc Drak, you''ll have to face a world that''s not at all like you remember it. Use your magical axe in creative ways - learn new attacks, wield elemental powers and dash high into the skies. This journey has a lot in store for you: travel through the war-torn countryside, the cliffs at the end of the world, explore ruined cities, caverns and abandoned mines, and restore the kingdom to its former glory.' FROM games WHERE igdb_id = 223748 ON CONFLICT (game_id, language_code) DO NOTHING;
