INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attack at Dawn: North Africa', 'Attack at Dawn: North Africa is an operational level wargame set in WW2 North African theatre. It features 3 campaigns, and 15 scenarios, which can be played in solo or multiplayer modes. It begins with the German troops probing into the Libyan region of Cyrenaica, and finishes either with the total defeat of German-Italian Panzer Armee, or with the British loss of Egypt and their retreat across the Suez Canal.' FROM games WHERE igdb_id = 143327 ON CONFLICT (game_id, language_code) DO NOTHING;
