INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aurorae-equitas', 310915, '2022-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8lax.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3hmi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aurorae Equitas', 'Slightly over-the-hill capybaras Rubina and Ceferino, a pair of old acquaintances, meet up at a rental cabin near the end of the year for the Aurorae Equitas, a recurring natural event that happens once every few decades. They quickly realize that no one else from their social group is showing up, they try to make the best of an awkward social situation and reminisce on their tangentially shared history while sharing a warm fire and a calming hot spring.' FROM games WHERE igdb_id = 310915 ON CONFLICT (game_id, language_code) DO NOTHING;
