INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epiphany City', 'Epiphany City is a mind-bending puzzle adventure game where you use magical picture frames to manipulate the world around you. Turn paintings to life, change time, & re-imagine objects to suit your needs. Follow Lily, a girl who’s lost all hope, as she steals powers from the strongest superhero, leaving it up to her to save the world.' FROM games WHERE igdb_id = 147508 ON CONFLICT (game_id, language_code) DO NOTHING;
