INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snowdreams -lost in winter-', '《Snowdreams》 is a romance visual novel game set in the eastern district of Taipei, narrating the difficulties that the main character Xie Zichen runs into whilst pursuing his dream of becoming a professional novelist, as well as his love story with Xia Qianfan and Xuejian. By combining refined illustrations, touching music, and exquisite acting, the game leads players on a touching experience of a story of dreams and yearning.' FROM games WHERE igdb_id = 146324 ON CONFLICT (game_id, language_code) DO NOTHING;
