INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boss Hunter', 'Join our Boss Hunting friend in this bite-size, indie developed, boss battle game. You will encounter 6 unique and challenging bosses to defeat, but don''t let the small number fool you. These are 6 bosses that won''t give up easily. You must have the Boss Hunter spirit!' FROM games WHERE igdb_id = 368679 ON CONFLICT (game_id, language_code) DO NOTHING;
