INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rank-warmaster', 148003, '2022-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30gy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1f5w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rank: Warmaster', 'Have you ever played a 4X game and wanted to experience more complex battles? Have you ever played an RTS and wanted meaningful exploration beyond the battle map? Have you ever played a Space Simulator and wanted more purpose than grinding for a better ship? Do you want a strategy game where your choices have consequences and defeat is always a possibility? For space game fans tired of the limited game play of singular genres we present Rank: Warmaster! With more depth than a 4X, broader exploration than an RTS, and more purpose than a Space Simulator Rank: Warmaster combines the best aspects of all three genres into a smooth blend to create a unique experience. If you''ve ever wished for a true multi-genre space game where you can take on any role from the commander of an empire down to the pilot of a singular ship, and to switch between them at any time, then Rank: Warmaster is the game for you!' FROM games WHERE igdb_id = 148003 ON CONFLICT (game_id, language_code) DO NOTHING;
