INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horrid Henry''s Krazy Karts', 'Play as Horrid Henry or race head-to-head as Rude Ralph, Moody Margaret, Perfect Peter, Brainy Brian or Singing Soraya and win cups and upgrades to become the ultimate Horrid Hero! Customize your kart in the workshop for extra advantage. Win perfect power-up tokens to leave everyone else standing! Control your kart as you swoop over awesome jumps and dodge obstacles, gross goo and loads of smelly snot slime! Multiplayer Mode to play with friends and create your own levels to challenge and share as you race through forty challenging levels in four fantastic themed locations.' FROM games WHERE igdb_id = 187451 ON CONFLICT (game_id, language_code) DO NOTHING;
