INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hand of Merlin', 'The Hand of Merlin is a turn-based rogue-lite RPG in which Arthurian legend clashes with cosmic horror. Recruit a company of up to three mortal heroes and guide them in spirit on a desperate journey from Albion to Jerusalem. Explore a richly-imagined medieval setting on the brink of apocalypse. Trade with merchants, improve your heroes and unearth ancient relics. Search for the lost fragments of your soul, scattered across the multiverse - and save as many worlds as you can.' FROM games WHERE igdb_id = 103591 ON CONFLICT (game_id, language_code) DO NOTHING;
