INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales From Toyotoki: Arrival of the Witch', 'A boy moves to a remote island in Okinawa and is informed that his grandfather, who was supposed to take care of him, has evaporated. When he is ready to fend for himself on the remote island, he meets a girl who calls herself a witch. The girl deals with magic from another world and life on a remote island where Ryukyuan culture is deeply rooted. What fate awaits them both? ────' FROM games WHERE igdb_id = 206553 ON CONFLICT (game_id, language_code) DO NOTHING;
