INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Violet', 'Catch, battle, and train Pokémon in the Paldea Region, a vast land filled with lakes, towering peaks, wastelands, small towns, and sprawling cities. Explore a wide-open world at your own pace and traverse land, water, and air by riding on a form-shifting Legendary Pokémon. Choose either Sprigatito, Fuecoco, or Quaxly, to be your first partner Pokémon before setting off on your journey through Paldea.' FROM games WHERE igdb_id = 191930 ON CONFLICT (game_id, language_code) DO NOTHING;
